const listRuns = `-- name: ListRuns :many
SELECT r.id, r.workspace_id, r.ticket_id, r.agent_id, r.mode, r.state, r.wait_reason, r.resolved_spec, r.definition_version_id, r.harness, r.model, r.harness_session_id, r.outcome, r.tool_calls, r.input_tokens, r.output_tokens, r.cost_usd_micros, r.cost_source, r.started_at, r.ended_at, r.created_at, r.updated_at, r.dispatched_by_user_id, r.runner_id, r.workspace_volume, r.idle_turns, r.parent_run_id, r.purpose, r.contract, r.checks, r.setup_ms, r.harness_ms, r.checks_ms, r.hold_until, r.hold_started_at, r.hold_attempts, r.hold_reset_known, r.checkpoint_branch, r.checkpoint_at, r.checkpoint_error, r.workspace_host_path, r.execution_token, r.execution_expires_at, r.context_tokens, r.report, r.rollover_requested FROM runs r
LEFT JOIN tickets t ON t.id = r.ticket_id
LEFT JOIN planning_sessions ps ON ps.run_id = r.id
LEFT JOIN LATERAL (
  SELECT c.project_id FROM chat_sessions c
  WHERE r.purpose = 'chat' AND (c.current_run_id = r.id OR c.id IN (SELECT m.session_id FROM chat_messages m WHERE m.run_id = r.id))
  LIMIT 1
) cs ON true
WHERE r.workspace_id = $1
  AND (r.parent_run_id IS NULL OR $2::uuid IS NOT NULL)
  AND ($2::uuid IS NULL OR r.ticket_id = $2)
  AND r.state = ANY($3::text[])
  AND ($4::uuid IS NULL OR r.agent_id = $4)
  AND ($5::text IS NULL OR r.purpose = $5)
  AND (NOT $6::bool OR r.purpose NOT IN ('chat', 'research', 'workflow', 'learning'))
  AND ($7::uuid IS NULL OR coalesce(t.project_id, ps.project_id, cs.project_id) = $7)
ORDER BY r.started_at DESC, r.id DESC
LIMIT 51 OFFSET $8::int
`

type ListRunsParams struct {
	WorkspaceID uuid.UUID
	TicketID    *uuid.UUID
	States      []string
	AgentID     *uuid.UUID
	Purpose     *string
	HideChat    bool
	ProjectID   *uuid.UUID
	Skip        int32
}

// Top-level runs for the Runs index. A run's project comes from its ticket,
// planning session or chat session; delegated runs are left to their parent
// unless the list is filtered to one ticket, where every run is listed.
// hide_chat leaves out Personal Assistant chat runs (they live in Chat).
func (q *Queries) ListRuns(ctx context.Context, arg ListRunsParams) ([]Run, error) {
	rows, err := q.db.Query(ctx, listRuns,
		arg.WorkspaceID,
		arg.TicketID,
		arg.States,
		arg.AgentID,
		arg.Purpose,
		arg.HideChat,
		arg.ProjectID,
		arg.Skip,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Run{}
	for rows.Next() {
		var i Run
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.TicketID,
			&i.AgentID,
			&i.Mode,
			&i.State,
			&i.WaitReason,
			&i.ResolvedSpec,
			&i.DefinitionVersionID,
			&i.Harness,
			&i.Model,
			&i.HarnessSessionID,
			&i.Outcome,
			&i.ToolCalls,
			&i.InputTokens,
			&i.OutputTokens,
			&i.CostUsdMicros,
			&i.CostSource,
			&i.StartedAt,
			&i.EndedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DispatchedByUserID,
			&i.RunnerID,
			&i.WorkspaceVolume,
			&i.IdleTurns,
			&i.ParentRunID,
			&i.Purpose,
			&i.Contract,
			&i.Checks,
			&i.SetupMs,
			&i.HarnessMs,
			&i.ChecksMs,
			&i.HoldUntil,
			&i.HoldStartedAt,
			&i.HoldAttempts,
			&i.HoldResetKnown,
			&i.CheckpointBranch,
			&i.CheckpointAt,
			&i.CheckpointError,
			&i.WorkspaceHostPath,
			&i.ExecutionToken,
			&i.ExecutionExpiresAt,
			&i.ContextTokens,
			&i.Report,
			&i.RolloverRequested,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

